/**
 * Client onboarding & property intake (/intake/<token>): the form's content and structure.
 *
 * Every label is copied word for word from docs/onboarding/Presence_Onboarding_2.0_{ENG,NL}.docx
 * (local only) and `npm run check` compares them (scripts/check-onboarding.ts). Do not edit a label
 * here without changing the .docx. Field keys are shared by both languages, so answers don't depend on
 * the language the form was filled in.
 */

export const INTAKE_LANGS = ["en", "nl"] as const;
