export type FieldKey = keyof typeof INTAKE_FIELDS;
/** Free text typed next to a ticked "Other:" / "Anders:" box. */
export const otherTextKey = (key: FieldKey) => `${key}.text`;

/** Identification block: the only part required before the client can submit. */
export const REQUIRED_KEYS: readonly FieldKey[] = ["id.property_name", "id.date", "id.contact_name", "id.role", "id.email", "id.phone", "id.address"];

export const CHOICE_VALUES = { yesNo: ["yes", "no"], yesNoUnknown: ["yes", "no", "unknown"] } as const;
export type ChoiceValue = "yes" | "no" | "unknown";
/** Answer format only (not form copy): the words the .docx use in "Yes / No / Unknown" / "Ja / Nee / Onbekend". */
export const CHOICE_LABELS: Record<IntakeLang, Record<ChoiceValue, string>> = {
  en: { yes: "Yes", no: "No", unknown: "Unknown" },
  nl: { yes: "Ja", no: "Nee", unknown: "Onbekend" },
};

/**
 * Asked as free text in the EN .docx but as "Ja / Nee" in the NL .docx. Both languages show radio
 * options (client decision 16-10); the EN label stays unchanged. Listed so the label test can allow it.
 * PENDING: add "Yes / No" to these questions in the EN .docx.
 */
export const YES_NO_ADDED_IN_EN: readonly FieldKey[] = [
  "s06.front_door_electronic", "s06.managed_firewall", "s07.fire_alarm_monitored", "s07.emergency_contacts", "s07.legionella_plan", "s07.legionella_sampling", "s07.housekeeping_digital", "s08.room_telephones", "s08.call_forwarding", "s08.whatsapp", "s08.live_chat", "s08.shared_inbox",
];

/** One form item; `raw` is the full .docx line when it carries the options ("Reception present? Yes / No"). */
export type IntakeItem = { key: FieldKey; label: string; raw?: string };
export type IntakeGroup = { title?: string; items: IntakeItem[] };
export type IntakeSection = { id: string; part?: string; title: string; desc?: string; groups: IntakeGroup[] };
export type IntakeDoc = { title: string; intro: string[]; ident: IntakeItem[]; sections: IntakeSection[]; closing: string };

